      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Depth-Width Duality</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0e27;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px;min-height:100vh}.container{max-width:900px;width:100%}h1{text-align:center;font-size:1.6em;margin-bottom:5px;background:linear-gradient(135deg,#00d2ff,#7a5cff);-webkit-background-clip:text;-webkit-text-fill-color:transparent}h2{text-align:center;font-size:.9em;color:#888;margin-bottom:20px}.controls{display:flex;gap:20px;justify-content:center;margin-bottom:20px;flex-wrap:wrap}.control{display:flex;flex-direction:column;align-items:center;background:#151a3a;padding:12px 20px;border-radius:10px;border:1px solid #2a3060}.control label{font-size:.8em;color:#aaa;margin-bottom:4px}.control .val{font-size:1.4em;font-weight:bold;color:#00d2ff;margin-bottom:4px}input[type=range]{width:180px;accent-color:#7a5cff}canvas{width:100%;border-radius:10px;background:#0d1230;border:1px solid #1a2050}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:15px}.stat{background:#151a3a;padding:12px;border-radius:8px;text-align:center;border:1px solid #2a3060}.stat .label{font-size:.7em;color:#888;text-transform:uppercase;letter-spacing:1px}.stat .value{font-size:1.3em;font-weight:bold;margin-top:4px}.stat .value.blue{color:#00d2ff}.stat .value.purple{color:#7a5cff}.stat .value.green{color:#00e676}.theorem{margin-top:15px;padding:12px;background:#1a1040;border-left:3px solid #7a5cff;border-radius:0 8px 8px 0;font-size:.85em;line-height:1.5}</style></head><body><div class=\"container\"><h1>Depth-Width Duality Explorer</h1><h2>Theorem: w<sup>L</sup> ≥ w · L for w ≥ 2, L ≥ 1</h2><div class=\"controls\"><div class=\"control\"><label>Width (w)</label><div class=\"val\" id=\"wVal\">4</div><input type=\"range\" id=\"wSlider\" min=\"2\" max=\"16\" value=\"4\"></div><div class=\"control\"><label>Max Depth (L)</label><div class=\"val\" id=\"lVal\">10</div><input type=\"range\" id=\"lSlider\" min=\"2\" max=\"20\" value=\"10\"></div></div><canvas id=\"chart\" height=\"350\"></canvas><div class=\"stats\"><div class=\"stat\"><div class=\"label\">Pieces (w<sup>L</sup>)</div><div class=\"value blue\" id=\"pieces\">—</div></div><div class=\"stat\"><div class=\"label\">Parameters (w·L)</div><div class=\"value purple\" id=\"params\">—</div></div><div class=\"stat\"><div class=\"label\">Efficiency Ratio</div><div class=\"value green\" id=\"ratio\">—</div></div></div><div class=\"theorem\"><strong>Formally verified:</strong> For any width w ≥ 2 and depth L ≥ 1, the expressiveness w<sup>L</sup> always exceeds the parameter count w·L. The ratio grows exponentially — each additional layer multiplies expressiveness by w while adding only O(w) parameters.</div></div><script>const canvas=document.getElementById('chart'),ctx=canvas.getContext('2d'),wSlider=document.getElementById('wSlider'),lSlider=document.getElementById('lSlider');function resize(){canvas.width=canvas.clientWidth*2;canvas.height=canvas.clientHeight*2;ctx.scale(2,2)}resize();window.addEventListener('resize',()=>{resize();draw()});function draw(){const w=parseInt(wSlider.value),maxL=parseInt(lSlider.value);document.getElementById('wVal').textContent=w;document.getElementById('lVal').textContent=maxL;const cw=canvas.width/2,ch=canvas.height/2,pad={t:30,r:30,b:40,l:60},pw=cw-pad.l-pad.r,ph=ch-pad.t-pad.b;ctx.clearRect(0,0,cw,ch);const pieces=[],params=[];for(let L=0;L<=maxL;L++){pieces.push(Math.pow(w,L));params.push(w*Math.max(L,1))}const maxVal=Math.max(...pieces),logMax=Math.log10(maxVal+1);ctx.strokeStyle='#2a3060';ctx.lineWidth=.5;ctx.fillStyle='#555';ctx.font='11px system-ui';ctx.textAlign='right';for(let i=0;i<=5;i++){const y=pad.t+ph*(1-i/5),val=Math.pow(10,logMax*i/5);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();ctx.fillText(val>=1e6?val.toExponential(0):Math.round(val).toLocaleString(),pad.l-5,y+4)}ctx.textAlign='center';for(let L=0;L<=maxL;L++){const x=pad.l+pw*L/maxL;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();ctx.fillText(L,x,pad.t+ph+15)}ctx.fillText('Depth (L)',pad.l+pw/2,pad.t+ph+32);function plotLine(data,color,width){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();data.forEach((v,i)=>{const x=pad.l+pw*i/maxL,ly=v>0?Math.log10(v)/logMax:0,y=pad.t+ph*(1-ly);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});ctx.stroke();ctx.lineWidth=1;data.forEach((v,i)=>{const x=pad.l+pw*i/maxL,ly=v>0?Math.log10(v)/logMax:0,y=pad.t+ph*(1-ly);ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()})}plotLine(params,'#7a5cff',2);plotLine(pieces,'#00d2ff',2);const effData=pieces.map((p,i)=>({L:i,eff:i>0?p/(w*i):1}));ctx.fillStyle='rgba(0,230,118,0.15)';ctx.beginPath();for(let i=0;i<=maxL;i++){const x=pad.l+pw*i/maxL,pLog=pieces[i]>0?Math.log10(pieces[i])/logMax:0,parLog=params[i]>0?Math.log10(params[i])/logMax:0;const yp=pad.t+ph*(1-pLog);i===0?ctx.moveTo(x,yp):ctx.lineTo(x,yp)}for(let i=maxL;i>=0;i--){const x=pad.l+pw*i/maxL,parLog=params[i]>0?Math.log10(params[i])/logMax:0;ctx.lineTo(x,pad.t+ph*(1-parLog))}ctx.closePath();ctx.fill();ctx.font='bold 11px system-ui';ctx.fillStyle='#00d2ff';ctx.fillText('w^L (pieces)',pad.l+pw*0.7,pad.t+15);ctx.fillStyle='#7a5cff';ctx.fillText('w·L (params)',pad.l+pw*0.7,pad.t+30);const finalPieces=pieces[maxL],finalParams=params[maxL],finalRatio=maxL>0?finalPieces/finalParams:1;document.getElementById('pieces').textContent=finalPieces>=1e9?finalPieces.toExponential(2):finalPieces.toLocaleString();document.getElementById('params').textContent=finalParams.toLocaleString();document.getElementById('ratio').textContent=finalRatio>=1e6?finalRatio.toExponential(1):Math.round(finalRatio).toLocaleString()+'×'}wSlider.addEventListener('input',draw);lSlider.addEventListener('input',draw);draw()</script></body></html>"
