x.textAlign='right';ctx.fillText(i,pad.l-5,y+3)}for(let i=-xRange;i<=xRange;i++){const x=tx(i);ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();ctx.fillStyle='#555';ctx.textAlign='center';ctx.fillText(i,x,pad.t+ph+12)}ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(tx(0),pad.t);ctx.lineTo(tx(0),pad.t+ph);ctx.stroke();ctx.beginPath();ctx.moveTo(pad.l,ty(0));ctx.lineTo(pad.l+pw,ty(0));ctx.stroke();const n=300;function plotFn(fn,color,lw,dash){ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.setLineDash(dash||[]);ctx.beginPath();for(let i=0;i<=n;i++){const x=-xRange+2*xRange*i/n,y=fn(x),px=tx(x),py=ty(y);if(py<pad.t-5||py>pad.t+ph+5)continue;i===0?ctx.moveTo(px,py):ctx.lineTo(px,py)}ctx.stroke();ctx.setLineDash([])}plotFn(relu,'#4a90ff',2);plotFn(x=>softplusTemp(beta,x),'#ff6b6b',2);plotFn(x=>softplusTemp(beta,x)-relu(x),'#ffa500',2.5);const log2=Math.log(2)/beta;ctx.strokeStyle='rgba(255,107,107,0.4)';ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(pad.l,ty(log2));ctx.lineTo(pad.l+pw,ty(log2));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(255,107,107,0.6)';ctx.font='10px system-ui';ctx.textAlign='left';ctx.fillText('log(2)/β = '+log2.toFixed(4),pad.l+5,ty(log2)-5);ctx.font='bold 10px system-ui';const legendX=pad.l+pw-130,legendY=pad.t+20;ctx.fillStyle='#4a90ff';ctx.fillText('■ ReLU',legendX,legendY);ctx.fillStyle='#ff6b6b';ctx.fillText('■ Softplus_β',legendX,legendY+14);ctx.fillStyle='#ffa500';ctx.fillText('■ Gap',legendX,legendY+28)}betaSlider.addEventListener('input',draw);rangeSlider.addEventListener('input',draw);draw()</script></body></html>"
