/sup> ≥ 1/(2ε) — precision-depth tradeoff for quantized ReLU networks</h2><div class=\"controls\"><div class=\"control\"><label>Target Accuracy (−log₁₀ε)</label><div class=\"val\" id=\"epsVal\">6</div><input type=\"range\" id=\"epsSlider\" min=\"1\" max=\"15\" value=\"6\"></div><div class=\"control\"><label>Network Depth (L)</label><div class=\"val\" id=\"depthVal\">8</div><input type=\"range\" id=\"depthSlider\" min=\"1\" max=\"20\" value=\"8\"></div><div class=\"control\"><label>Weight Bits</label><div class=\"val\" id=\"bitsVal\">8</div><input type=\"range\" id=\"bitsSlider\" min=\"1\" max=\"32\" value=\"8\"></div></div><div class=\"grid\"><div class=\"card\"><h3>📊 Required vs Available Precision</h3><div id=\"precisionInfo\"></div></div><div class=\"card\"><h3>📋 Depth Scan (fixed ε and bits)</h3><div id=\"depthScan\"></div></div></div><div class=\"card\"><h3>🔢 Bit-Width Requirements Across Accuracies</h3><div id=\"bitTable\"></div></div><div class=\"theorem\"><strong>Formally verified (Theorem 18):</strong> A ReLU network with integer weights bounded by B and depth L outputs rationals with denominators dividing B<sup>L</sup>. To ε-approximate an irrational, B<sup>L</sup> ≥ 1/(2ε). This yields the minimum bit-width per weight: ⌈log₂(1/(2ε)) / L⌉ bits.</div></div><script>const epsSlider=document.getElementById('epsSlider'),depthSlider=document.getElementById('depthSlider'),bitsSlider=document.getElementById('bitsSlider');function fmt(n){if(n>=1e15)return n.toExponential(1);if(n>=1e6)return n.toExponential(2);return Math.round(n).toLocaleString()}function update(){const negLogEps=parseInt(epsSlider.value),L=parseInt(depthSlider.value),bits=parseInt(bitsSlider.value);document.getElementById('epsVal').textContent=negLogEps;document.getElementById('depthVal').textContent=L;document.getElementById('bitsVal').textContent=bits;const eps=Math.pow(10,-negLogEps),required=1/(2*eps),B=Math.pow(2,bits),available=Math.pow(B,L),minB=Math.pow(required,1/L),minBits=Math.ceil(Math.log2(minB)),sufficient=available>=required;let pi=document.getElementById('precisionInfo');pi.innerHTML=`<table><tr><td>Target accuracy ε</td><td class=\"highlight\">10<sup>−${negLogEps}</sup></td></tr><tr><td>Required B<sup>L</sup> ≥ 1/(2ε)</td><td class=\"highlight\">${fmt(required)}</td></tr><tr><td>Available B<sup>L</sup> = ${Math.pow(2,bits)}<sup>${L}</sup></td><td class=\"${sufficient?'ok':'warn'}\">${fmt(available)}</td></tr><tr><td>Min weight bound B*</td><td>${minB.toFixed(2)}</td></tr><tr><td>Min bits per weight</td><td class=\"${bits>=minBits?'ok':'warn'}\">${minBits} ${bits>=minBits?'✓ (have '+bits+')':'✗ (have '+bits+')'}</td></tr><tr><td>Status</td><td class=\"${sufficient?'ok':'warn'}\">${sufficient?'✅ Sufficient precision':'❌ Insufficient — increase depth or bits'}</td></tr></table>`;let ds='<table><tr><th>L</th><th>Min bits</th><th>Status ('+bits+'-bit)</th><th>Margin</th></tr>';for(let d=1;d<=Math.min(20,L+6);d++){const mb=Math.ceil(Math.log2(Math.pow(required,1/d)));const ok=bits>=mb;const margin=ok?Math.pow(Math.pow(2,bits),d)/required:0;const markerL=d===L?' ◄':'';ds+=`<tr><td>${d}${markerL}</td><td>${mb}</td><td class=\"${ok?'ok':'warn'}\">${ok?'✓':'✗'}</td><td>${ok?fmt(margin)+'×':'—'}</td></tr>`}ds+='</table>';document.getElementById('depthScan').innerHTML=ds;let bt='<table><tr><th>−log₁₀ε</th>';for(let d=2;d<=16;d+=2)bt+=`<th>L=${d}</th>`;bt+='</tr>';for(let e=1;e<=12;e++){bt+=`<tr><td>${e}</td>`;const req=Math.pow(10,e)/2;for(let d=2;d<=16;d+=2){const mb=Math.max(1,Math.ceil(Math.log2(Math.pow(req,1/d))));const cls=mb<=8?'ok':mb<=16?'highlight':'warn';bt+=`<td class=\"${cls}\">${mb}</td>`}bt+='</tr>'}bt+='</table>';document.getElementById('bitTable').innerHTML=bt}epsSlider.addEventListener('input',update);depthSlider.addEventListener('input',update);bitsSlider.addEventListener('input',update);update()</script></body></html>"
