eight=\"400\"></canvas><div class=\"info\"><div class=\"info-box\"><strong>Gap Formula (Theorem 12):</strong><br>For x ≥ 0: <span class=\"formula\">gap(x) = log(1 + e<sup>−x</sup>)</span><br>Maximum at x = 0: <span class=\"bound\">gap(0) = log 2 ≈ 0.693</span><br>Decays exponentially as |x| → ∞</div><div class=\"info-box\"><strong>Temperature Scaling (Theorem 11):</strong><br>Gap ≤ <span class=\"formula\">log(2) / β</span><br>Current β: <span class=\"bound\" id=\"curBeta\">1.0</span> → bound: <span class=\"bound\" id=\"curBound\">0.693</span><br>As β → ∞, softplus<sub>β</sub> → ReLU (tropical limit)</div></div></div><script>const canvas=document.getElementById('chart'),ctx=canvas.getContext('2d'),betaSlider=document.getElementById('betaSlider'),rangeSlider=document.getElementById('rangeSlider');function resize(){canvas.width=canvas.clientWidth*2;canvas.height=canvas.clientHeight*2;ctx.scale(2,2)}resize();window.addEventListener('resize',()=>{resize();draw()});function softplus(x){if(x>20)return x;if(x<-20)return Math.exp(x);return Math.log(1+Math.exp(x))}function relu(x){return Math.max(0,x)}function softplusTemp(b,x){return softplus(b*x)/b}function draw(){const beta=parseInt(betaSlider.value)/10,xRange=parseInt(rangeSlider.value);document.getElementById('betaVal').textContent=beta.toFixed(1);document.getElementById('rangeVal').textContent='±'+xRange;document.getElementById('curBeta').textContent=beta.toFixed(1);document.getElementById('curBound').textContent=(Math.log(2)/beta).toFixed(4);const cw=canvas.width/2,ch=canvas.height/2,pad={t:25,r:20,b:35,l:50},pw=cw-pad.l-pad.r,ph=ch-pad.t-pad.b;ctx.clearRect(0,0,cw,ch);const yMin=-0.5,yMax=xRange+1;function tx(x){return pad.l+pw*(x+xRange)/(2*xRange)}function ty(y){return pad.t+ph*(1-(y-yMin)/(yMax-yMin))}ctx.strokeStyle='#1a2050';ctx.lineWidth=.5;for(let i=Math.ceil(yMin);i<=yMax;i++){const y=ty(i);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();ctx.fillStyle='#555';ctx.font='10px system-ui';ctx.textAlign='right';ctx.fillText(i,pad.l-5,y+3)}for(let i=-xRange;i<=xRange;i++){const x=tx(i);ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();ctx.fillStyle='#555';ctx.textAlign='center';ctx.fillText(i,x,pad.t+ph+12)}ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(tx(0),pad.t);ctx.lineTo(tx(0),pad.t+ph);ctx.stroke();ctx.beginPath();ctx.moveTo(pad.l,ty(0));ctx.lineTo(pad.l+pw,ty(0));ctx.stroke();const n=300;function plotFn(fn,color,lw,dash){ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.setLineDash(dash||[]);ctx.beginPath();for(let i=0;i<=n;i++){const x=-xRange+2*xRange*i/n,y=fn(x),px=tx(x),py=ty(y);if(py<pad.t-5||py>pad.t+ph+5)continue;i===0?ctx.moveTo(px,py):ctx.lineTo(px,py)}ctx.stroke();ctx.setLineDash([])}plotFn(relu,'#4a90ff',2);plotFn(x=>softplusTemp(beta,x),'#ff6b6b',2);plotFn(x=>softplusTemp(beta,x)-relu(x),'#ffa500',2.5);const log2=Math.log(2)/beta;ctx.strokeStyle='rgba(255,107,107,0.4)';ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(pad.l,ty(log2));ctx.lineTo(pad.l+pw,ty(log2));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(255,107,107,0.6)';ctx.font='10px system-ui';ctx.textAlign='left';ctx.fillText('log(2)/β = '+log2.toFixed(4),pad.l+5,ty(log2)-5);ctx.font='bold 10px system-ui';const legendX=pad.l+pw-130,legendY=pad.t+20;ctx.fillStyle='#4a90ff';ctx.fillText('■ ReLU',legendX,legendY);ctx.fillStyle='#ff6b6b';ctx.fillText('■ Softplus_β',legendX,legendY+14);ctx.fillStyle='#ffa500';ctx.fillText('■ Gap',legendX,legendY+28)}betaSlider.addEventListener('input',draw);rangeSlider.addEventListener('input',draw);draw()</script></body></html>"
