      "title": "Tropical Bridge: Softplus-ReLU Gap",
      "description": "Interactive visualization of the softplus-ReLU gap, showing how the tropical defect log(1+exp(-|x|)) is bounded by log(2) and varies with temperature β.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Tropical Bridge</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0e27;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px;min-height:100vh}.container{max-width:900px;width:100%}h1{text-align:center;font-size:1.5em;margin-bottom:5px;background:linear-gradient(135deg,#ff6b6b,#ffa500);-webkit-background-clip:text;-webkit-text-fill-color:transparent}h2{text-align:center;font-size:.85em;color:#888;margin-bottom:20px}.controls{display:flex;gap:20px;justify-content:center;margin-bottom:15px;flex-wrap:wrap}.control{display:flex;flex-direction:column;align-items:center;background:#1a1530;padding:10px 18px;border-radius:10px;border:1px solid #3a2060}.control label{font-size:.75em;color:#aaa;margin-bottom:3px}.control .val{font-size:1.3em;font-weight:bold;color:#ffa500;margin-bottom:3px}input[type=range]{width:200px;accent-color:#ff6b6b}canvas{width:100%;border-radius:10px;background:#0d1030;border:1px solid #1a1850}.info{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.info-box{background:#1a1530;padding:10px;border-radius:8px;border:1px solid #3a2060;font-size:.85em;line-height:1.5}.formula{color:#ffa500;font-family:'Courier New',monospace;font-weight:bold}.bound{color:#ff6b6b}</style></head><body><div class=\"container\"><h1>The Tropical Bridge</h1><h2>Softplus(x) − ReLU(x) = log(1 + e<sup>−|x|</sup>) ≤ log 2</h2><div class=\"controls\"><div class=\"control\"><label>Temperature β</label><div class=\"val\" id=\"betaVal\">1.0</div><input type=\"range\" id=\"betaSlider\" min=\"1\" max=\"100\" value=\"10\"></div><div class=\"control\"><label>X Range</label><div class=\"val\" id=\"rangeVal\">±6</div><input type=\"range\" id=\"rangeSlider\" min=\"2\" max=\"15\" value=\"6\"></div></div><canvas id=\"chart\" height=\"400\"></canvas><div class=\"info\"><div class=\"info-box\"><strong>Gap Formula (Theorem 12):</strong><br>For x ≥ 0: <span class=\"formula\">gap(x) = log(1 + e<sup>−x</sup>)</span><br>Maximum at x = 0: <span class=\"bound\">gap(0) = log 2 ≈ 0.693</span><br>Decays exponentially as |x| → ∞</div><div class=\"info-box\"><strong>Temperature Scaling (Theorem 11):</strong><br>Gap ≤ <span class=\"formula\">log(2) / β</span><br>Current β: <span class=\"bound\" id=\"curBeta\">1.0</span> → bound: <span class=\"bound\" id=\"curBound\">0.693</span><br>As β → ∞, softplus<sub>β</sub> → ReLU (tropical limit)</div></div></div><script>const canvas=document.getElementById('chart'),ctx=canvas.getContext('2d'),betaSlider=document.getElementById('betaSlider'),rangeSlider=document.getElementById('rangeSlider');function resize(){canvas.width=canvas.clientWidth*2;canvas.height=canvas.clientHeight*2;ctx.scale(2,2)}resize();window.addEventListener('resize',()=>{resize();draw()});function softplus(x){if(x>20)return x;if(x<-20)return Math.exp(x);return Math.log(1+Math.exp(x))}function relu(x){return Math.max(0,x)}function softplusTemp(b,x){return softplus(b*x)/b}function draw(){const beta=parseInt(betaSlider.value)/10,xRange=parseInt(rangeSlider.value);document.getElementById('betaVal').textContent=beta.toFixed(1);document.getElementById('rangeVal').textContent='±'+xRange;document.getElementById('curBeta').textContent=beta.toFixed(1);document.getElementById('curBound').textContent=(Math.log(2)/beta).toFixed(4);const cw=canvas.width/2,ch=canvas.height/2,pad={t:25,r:20,b:35,l:50},pw=cw-pad.l-pad.r,ph=ch-pad.t-pad.b;ctx.clearRect(0,0,cw,ch);const yMin=-0.5,yMax=xRange+1;function tx(x){return pad.l+pw*(x+xRange)/(2*xRange)}function ty(y){return pad.t+ph*(1-(y-yMin)/(yMax-yMin))}ctx.strokeStyle='#1a2050';ctx.lineWidth=.5;for(let i=Math.ceil(yMin);i<=yMax;i++){const y=ty(i);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();ctx.fillStyle='#555';ctx.font='10px system-ui';ctx.textAlign='right';ctx.fillText(i,pad.l-5,y+3)}for(let i=-xRange;i<=xRange;i++){const x=tx(i);ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();ctx.fillStyle='#555';ctx.textAlign='center';ctx.fillText(i,x,pad.t+ph+12)}ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(tx(0),pad.t);ctx.lineTo(tx(0),pad.t+ph);ctx.stroke();ctx.beginPath();ctx.moveTo(pad.l,ty(0));ctx.lineTo(pad.l+pw,ty(0));ctx.stroke();const n=300;function plotFn(fn,color,lw,dash){ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.setLineDash(dash||[]);ctx.beginPath();for(let i=0;i<=n;i++){const x=-xRange+2*xRange*i/n,y=fn(x),px=tx(x),py=ty(y);if(py<pad.t-5||py>pad.t+ph+5)continue;i===0?ctx.moveTo(px,py):ctx.lineTo(px,py)}ctx.stroke();ctx.setLineDash([])}plotFn(relu,'#4a90ff',2);plotFn(x=>softplusTemp(beta,x),'#ff6b6b',2);plotFn(x=>softplusTemp(beta,x)-relu(x),'#ffa500',2.5);const log2=Math.log(2)/beta;ctx.strokeStyle='rgba(255,107,107,0.4)';ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(pad.l,ty(log2));ctx.lineTo(pad.l+pw,ty(log2));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(255,107,107,0.6)';ctx.font='10px system-ui';ctx.textAlign='left';ctx.fillText('log(2)/β = '+log2.toFixed(4),pad.l+5,ty(log2)-5);ctx.font='bold 10px system-ui';const legendX=pad.l+pw-130,legendY=pad.t+20;ctx.fillStyle='#4a90ff';ctx.fillText('■ ReLU',legendX,legendY);ctx.fillStyle='#ff6b6b';ctx.fillText('■ Softplus_β',legendX,legendY+14);ctx.fillStyle='#ffa500';ctx.fillText('■ Gap',legendX,legendY+28)}betaSlider.addEventListener('input',draw);rangeSlider.addEventListener('input',draw);draw()</script></body></html>"
    },
    {
      "title": "Quantization Budget Calculator",
      "description": "Interactive tool for exploring the precision-depth tradeoff: given a target accuracy ε and network depth L, compute the minimum weight bit-width needed (B^L ≥ 1/(2ε)).",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Quantization Bounds</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0e27;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px;min-height:100vh}.container{max-width:900px;width:100%}h1{text-align:center;font-size:1.5em;margin-bottom:5px;background:linear-gradient(135deg,#00e676,#00bcd4);-webkit-background-clip:text;-webkit-text-fill-color:transparent}h2{text-align:center;font-size:.85em;color:#888;margin-bottom:20px}.controls{display:flex;gap:15px;justify-content:center;margin-bottom:15px;flex-wrap:wrap}.control{display:flex;flex-direction:column;align-items:center;background:#0d1a1a;padding:10px 16px;border-radius:10px;border:1px solid #1a4040}.control label{font-size:.75em;color:#aaa;margin-bottom:3px}.control .val{font-size:1.2em;font-weight:bold;color:#00e676;margin-bottom:3px}input[type=range]{width:160px;accent-color:#00e676}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}.card{background:#0d1a1a;padding:14px;border-radius:10px;border:1px solid #1a4040}.card h3{font-size:.85em;color:#00bcd4;margin-bottom:8px}table{width:100%;border-collapse:collapse;font-size:.8em}th{text-align:left;padding:4px 6px;color:#888;border-bottom:1px solid #1a4040;font-weight:normal}td{padding:4px 6px;border-bottom:1px solid #0a2020}.highlight{color:#00e676;font-weight:bold}.warn{color:#ff6b6b}.ok{color:#00e676}.bar{height:8px;border-radius:4px;background:#1a4040;position:relative;overflow:hidden}.bar-fill{height:100%;border-radius:4px;transition:width .3s}.theorem{margin-top:12px;padding:10px;background:#0a1a20;border-left:3px solid #00e676;border-radius:0 8px 8px 0;font-size:.82em;line-height:1.5}</style></head><body><div class=\"container\"><h1>Quantization Budget Calculator</h1><h2>Theorem: B<sup>L</sup> ≥ 1/(2ε) — precision-depth tradeoff for quantized ReLU networks</h2><div class=\"controls\"><div class=\"control\"><label>Target Accuracy (−log₁₀ε)</label><div class=\"val\" id=\"epsVal\">6</div><input type=\"range\" id=\"epsSlider\" min=\"1\" max=\"15\" value=\"6\"></div><div class=\"control\"><label>Network Depth (L)</label><div class=\"val\" id=\"depthVal\">8</div><input type=\"range\" id=\"depthSlider\" min=\"1\" max=\"20\" value=\"8\"></div><div class=\"control\"><label>Weight Bits</label><div class=\"val\" id=\"bitsVal\">8</div><input type=\"range\" id=\"bitsSlider\" min=\"1\" max=\"32\" value=\"8\"></div></div><div class=\"grid\"><div class=\"card\"><h3>📊 Required vs Available Precision</h3><div id=\"precisionInfo\"></div></div><div class=\"card\"><h3>📋 Depth Scan (fixed ε and bits)</h3><div id=\"depthScan\"></div></div></div><div class=\"card\"><h3>🔢 Bit-Width Requirements Across Accuracies</h3><div id=\"bitTable\"></div></div><div class=\"theorem\"><strong>Formally verified (Theorem 18):</strong> A ReLU network with integer weights bounded by B and depth L outputs rationals with denominators dividing B<sup>L</sup>. To ε-approximate an irrational, B<sup>L</sup> ≥ 1/(2ε). This yields the minimum bit-width per weight: ⌈log₂(1/(2ε)) / L⌉ bits.</div></div><script>const epsSlider=document.getElementById('epsSlider'),depthSlider=document.getElementById('depthSlider'),bitsSlider=document.getElementById('bitsSlider');function fmt(n){if(n>=1e15)return n.toExponential(1);if(n>=1e6)return n.toExponential(2);return Math.round(n).toLocaleString()}function update(){const negLogEps=parseInt(epsSlider.value),L=parseInt(depthSlider.value),bits=parseInt(bitsSlider.value);document.getElementById('epsVal').textContent=negLogEps;document.getElementById('depthVal').textContent=L;document.getElementById('bitsVal').textContent=bits;const eps=Math.pow(10,-negLogEps),required=1/(2*eps),B=Math.pow(2,bits),available=Math.pow(B,L),minB=Math.pow(required,1/L),minBits=Math.ceil(Math.log2(minB)),sufficient=available>=required;let pi=document.getElementById('precisionInfo');pi.innerHTML=`<table><tr><td>Target accuracy ε</td><td class=\"highlight\">10<sup>−${negLogEps}</sup></td></tr><tr><td>Required B<sup>L</sup> ≥ 1/(2ε)</td><td class=\"highlight\">${fmt(required)}</td></tr><tr><td>Available B<sup>L</sup> = ${Math.pow(2,bits)}<sup>${L}</sup></td><td class=\"${sufficient?'ok':'warn'}\">${fmt(available)}</td></tr><tr><td>Min weight bound B*</td><td>${minB.toFixed(2)}</td></tr><tr><td>Min bits per weight</td><td class=\"${bits>=minBits?'ok':'warn'}\">${minBits} ${bits>=minBits?'✓ (have '+bits+')':'✗ (have '+bits+')'}</td></tr><tr><td>Status</td><td class=\"${sufficient?'ok':'warn'}\">${sufficient?'✅ Sufficient precision':'❌ Insufficient — increase depth or bits'}</td></tr></table>`;let ds='<table><tr><th>L</th><th>Min bits</th><th>Status ('+bits+'-bit)</th><th>Margin</th></tr>';for(let d=1;d<=Math.min(20,L+6);d++){const mb=Math.ceil(Math.log2(Math.pow(required,1/d)));const ok=bits>=mb;const margin=ok?Math.pow(Math.pow(2,bits),d)/required:0;const markerL=d===L?' ◄':'';ds+=`<tr><td>${d}${markerL}</td><td>${mb}</td><td class=\"${ok?'ok':'warn'}\">${ok?'✓':'✗'}</td><td>${ok?fmt(margin)+'×':'—'}</td></tr>`}ds+='</table>';document.getElementById('depthScan').innerHTML=ds;let bt='<table><tr><th>−log₁₀ε</th>';for(let d=2;d<=16;d+=2)bt+=`<th>L=${d}</th>`;bt+='</tr>';for(let e=1;e<=12;e++){bt+=`<tr><td>${e}</td>`;const req=Math.pow(10,e)/2;for(let d=2;d<=16;d+=2){const mb=Math.max(1,Math.ceil(Math.log2(Math.pow(req,1/d))));const cls=mb<=8?'ok':mb<=16?'highlight':'warn';bt+=`<td class=\"${cls}\">${mb}</td>`}bt+='</tr>'}bt+='</table>';document.getElementById('bitTable').innerHTML=bt}epsSlider.addEventListener('input',update);depthSlider.addEventListener('input',update);bitsSlider.addEventListener('input',update);update()</script></body></html>"
    }
